// Verify a Stripe webhook signature header ("t=...,v1=...") via HMAC-SHA256.
async function verifyStripeSig(payload, sigHeader, secret) {
  if (!sigHeader || !secret) return false;
  const parts = Object.fromEntries(sigHeader.split(",").map(p => p.split("=")));
  if (!parts.t || !parts.v1) return false;
  const key = await crypto.subtle.importKey("raw", new TextEncoder().encode(secret), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
  const sig = await crypto.subtle.sign("HMAC", key, new TextEncoder().encode(`${parts.t}.${payload}`));
  const hex = [...new Uint8Array(sig)].map(b => b.toString(16).padStart(2, "0")).join("");
  if (hex.length !== parts.v1.length) return false;
  let diff = 0; for (let i = 0; i < hex.length; i++) diff |= hex.charCodeAt(i) ^ parts.v1.charCodeAt(i);
  return diff === 0;
}
// Apply a verified Stripe event to the tenant store.
async function handleStripeEvent(env, evt) {
  const o = (evt.data && evt.data.object) || {};
  let sub = null, t = null;
  if (evt.type === "checkout.session.completed") {
    sub = o.client_reference_id || (o.metadata && o.metadata.sub) || null;
    t = sub ? await getTenant(env, sub) : null;
    if (t) {
      if (t.status !== "active") t.status = "pending";       // paid; now awaiting Toast approval
      t.stripeCustomer = o.customer || t.stripeCustomer;
      t.stripeSub = o.subscription || t.stripeSub;
      t.billing = "trialing";
      t.trialEnd = Date.now() + 7 * 86400000;
    }
  } else if (evt.type === "customer.subscription.updated") {
    sub = await subByStripe(env, o.id, o.customer); t = sub ? await getTenant(env, sub) : null;
    if (t) {
      t.billing = o.status;
      if (o.status === "past_due" || o.status === "unpaid") t.status = "past_due";
      else if ((o.status === "active" || o.status === "trialing") && t.status === "past_due") t.status = "active";
      if (o.trial_end) t.trialEnd = o.trial_end * 1000;
    }
  } else if (evt.type === "customer.subscription.deleted") {
    sub = await subByStripe(env, o.id, o.customer); t = sub ? await getTenant(env, sub) : null;
    if (t) { t.status = "canceled"; t.billing = "canceled"; }
  } else if (evt.type === "invoice.payment_failed") {
    sub = await subByStripe(env, o.subscription, o.customer); t = sub ? await getTenant(env, sub) : null;
    if (t) t.status = "past_due";
  }
  if (sub && t) await saveTenant(env, sub, t);
}

const HTML = { "Content-Type": "text/html; charset=utf-8" };
