// ---- legal pages (Terms of Service + Privacy Policy) ----
// TEMPLATE (not legal advice). Company name defaults to "Coursed" and governing law to North Carolina, USA;
// replace with the operating legal entity + chosen jurisdiction and review with counsel before relying on these.
const LEGAL_UPDATED = "August 9, 2026";
function legalPage(title, sections) {
  const body = sections.map(s => `<h2>${s.h}</h2>${s.p.map(x => `<p>${x}</p>`).join("")}`).join("");
  return `<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Coursed — ${title}</title>
<style>
 :root{--bg:#0f0d0b;--panel:#1c1815;--line:#3a322b;--ink:#f6efe4;--muted:#b3a897;--faint:#7c7266;--gold:#f0b429}
 *{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Helvetica,Arial,sans-serif;line-height:1.65;-webkit-font-smoothing:antialiased}
 a{color:var(--gold);text-decoration:none}a:hover{text-decoration:underline}
 .nav{display:flex;justify-content:space-between;align-items:center;padding:20px 30px;max-width:860px;margin:0 auto;border-bottom:1px solid var(--line)}
 .logo{font-size:20px;font-weight:800}.logo .amp{color:var(--gold)}
 .wrap{max-width:760px;margin:0 auto;padding:34px 30px 20px}
 h1{font-size:30px;margin:0 0 6px}.upd{color:var(--faint);font-size:13px;margin-bottom:24px}
 h2{font-size:17px;margin:26px 0 8px;color:var(--gold)}
 p{color:var(--muted);margin:0 0 12px}
 footer{border-top:1px solid var(--line);padding:24px 30px 40px;max-width:860px;margin:26px auto 0;color:var(--faint);font-size:13px;display:flex;gap:16px;flex-wrap:wrap}
</style></head><body>
 <div class="nav"><a class="logo" href="/">Coursed <span class="amp">&#9733;</span></a><a href="/">&#8592; Home</a></div>
 <div class="wrap"><h1>${title}</h1><div class="upd">Last updated ${LEGAL_UPDATED}</div>${body}</div>
 <footer><a href="/">Home</a><a href="/terms">Terms</a><a href="/privacy">Privacy</a><a href="mailto:support@getcoursed.com">support@getcoursed.com</a></footer>
</body></html>`;
}
const TERMS_PAGE = legalPage("Terms of Service", [
  { h: "1. Agreement", p: ["These Terms of Service (“Terms”) govern your access to and use of Coursed (the “Service”), operated by Coursed (“we”, “us”, “our”). By creating an account, connecting a point-of-sale system, or using the Service, you agree to these Terms. If you are using the Service on behalf of a business, you represent that you are authorized to bind that business."] },
  { h: "2. The Service", p: ["Coursed reads order and sales data from your connected point-of-sale provider (such as Toast) and turns it into a service-performance scoreboard for your restaurant, including per-table scoring, timing flags, and staff leaderboards. Features vary by subscription plan. We may add, change, or remove features over time."] },
  { h: "3. Accounts and security", p: ["Access to a location’s board is protected by a password you set. You are responsible for keeping credentials confidential and for all activity that occurs under your account. Notify us promptly at support@getcoursed.com if you believe access has been compromised. You must provide accurate account and billing information and keep it current."] },
  { h: "4. Subscriptions, trials, and billing", p: ["Paid plans and optional add-ons (including the Pace add-on) are billed in advance on a recurring monthly or annual basis through our payment processor, Stripe. Free trials, where offered, convert to a paid subscription unless cancelled before the trial ends. Subscriptions renew automatically for the same term until cancelled. Fees are exclusive of taxes, which you are responsible for where applicable. We may change pricing on renewal with reasonable notice."] },
  { h: "5. Cancellation and refunds", p: ["You may cancel at any time; cancellation takes effect at the end of the current billing period, and the board goes offline at that point. Except where required by law, fees already paid are non-refundable and we do not provide prorated refunds for partial periods."] },
  { h: "6. Acceptable use", p: ["You agree not to misuse the Service, including: attempting to gain unauthorized access to other locations or accounts; probing, scanning, or testing the vulnerability of the Service; reverse engineering or copying the software except as permitted by law; reselling or providing the Service to third parties without our consent; or using the Service to violate any law or the rights of others, including your staff."] },
  { h: "7. Your data", p: ["As between you and us, you own the restaurant and operational data you connect or that we ingest on your behalf (“Customer Data”). You grant us a limited license to host, process, and display Customer Data solely to provide and improve the Service. You are responsible for having the necessary rights and notices to share staff and operational data with us, and for your use of the performance information the Service produces. Our handling of personal data is described in our Privacy Policy."] },
  { h: "8. Third-party services", p: ["The Service integrates with third parties such as your point-of-sale provider (Toast), Stripe for payments, and Cloudflare for hosting and delivery. Your use of those services is governed by their own terms, and we are not responsible for their availability or acts."] },
  { h: "9. Availability", p: ["We work to keep the Service available and accurate but provide it on an “as is” and “as available” basis. Scores and flags are derived from third-party POS data and are intended as operational guidance, not a definitive record. We do not guarantee uninterrupted or error-free operation and may perform maintenance or updates that temporarily affect availability."] },
  { h: "10. Intellectual property", p: ["The Service, including its software, design, and content (excluding Customer Data), is owned by us and protected by intellectual-property laws. We grant you a limited, non-exclusive, non-transferable right to use the Service during your subscription. All rights not expressly granted are reserved."] },
  { h: "11. Disclaimers and limitation of liability", p: ["To the maximum extent permitted by law, we disclaim all warranties, express or implied, including merchantability, fitness for a particular purpose, and non-infringement. To the maximum extent permitted by law, our total liability arising out of or relating to the Service will not exceed the amounts you paid us for the Service in the twelve months before the claim, and we will not be liable for indirect, incidental, special, consequential, or punitive damages, or lost profits or revenue."] },
  { h: "12. Indemnification", p: ["You agree to indemnify and hold us harmless from claims, damages, and expenses arising out of your Customer Data, your use of the Service, or your violation of these Terms or applicable law, including claims by your staff or customers relating to data you provide."] },
  { h: "13. Termination", p: ["You may stop using the Service at any time. We may suspend or terminate access if you breach these Terms, fail to pay, or use the Service in a way that risks harm to us or others. On termination, your right to use the Service ends; we may delete Customer Data after a reasonable period unless retention is required by law."] },
  { h: "14. Changes to these Terms", p: ["We may update these Terms from time to time. If we make material changes, we will update the “last updated” date and, where appropriate, provide notice. Continued use of the Service after changes take effect constitutes acceptance."] },
  { h: "15. Governing law", p: ["These Terms are governed by the laws of the State of North Carolina, USA, without regard to conflict-of-laws rules, and you agree to the exclusive jurisdiction of the state and federal courts located there, except where applicable law provides otherwise."] },
  { h: "16. Contact", p: ["Questions about these Terms: <a href=\"mailto:support@getcoursed.com\">support@getcoursed.com</a>."] }
]);
const PRIVACY_PAGE = legalPage("Privacy Policy", [
  { h: "Overview", p: ["This Privacy Policy explains what information Coursed (“we”, “us”) collects, how we use it, and your choices. It applies to the Coursed service and website. It does not cover the separate privacy practices of your point-of-sale provider or other third parties."] },
  { h: "Information we collect", p: ["<b>Account information</b> — the name, email address, restaurant name, and password you provide when signing up.", "<b>Billing information</b> — processed by our payment processor, Stripe. We receive limited billing status and identifiers from Stripe; we do not store full payment-card numbers on our systems.", "<b>Operational data from your POS</b> — to produce scoreboards we ingest order, check, item, table, timing, and employee data from your connected point-of-sale provider (such as Toast). This can include staff names and performance-related information.", "<b>Usage and log data</b> — basic technical information such as IP address and request logs, used for security, rate-limiting, and reliability."] },
  { h: "How we use information", p: ["We use information to provide, secure, and improve the Service; to calculate and display scores, timing flags, and leaderboards; to process subscriptions and billing; to provide support; and to comply with legal obligations. We do not sell your information, and we do not use it to serve third-party advertising."] },
  { h: "How information is shared", p: ["We share information with service providers who help us run the Service, including Stripe (payments), Cloudflare (hosting, delivery, and storage), and your POS provider (data integration). These providers process data on our behalf under their own terms. We may disclose information if required by law or to protect the rights, safety, and security of Coursed, our users, or others."] },
  { h: "Staff and restaurant data", p: ["The Service displays staff names and service-performance information that the restaurant chooses to connect. For that data, the restaurant is responsible as the controller, including for providing any notices to staff and having a lawful basis to use the information. We process it on the restaurant’s behalf to provide the Service."] },
  { h: "Data retention", p: ["We retain account and operational data for as long as your account is active and as needed to provide the Service, then for a reasonable period afterward unless a longer period is required by law. You can request an export or deletion of your data by contacting us."] },
  { h: "Security", p: ["We use measures designed to protect information, including encryption in transit, salted password hashing, signed session tokens, and access controls. No method of transmission or storage is completely secure, and we cannot guarantee absolute security."] },
  { h: "Your rights and choices", p: ["Depending on your location, you may have rights to access, correct, export, or delete personal information, and to object to or restrict certain processing. To exercise these rights, contact us at support@getcoursed.com; we may need to verify your identity. Where a restaurant controls staff data, we will refer requests to that restaurant as appropriate."] },
  { h: "Cookies", p: ["We use a small number of strictly necessary cookies to keep you signed in and to operate the board (for example, a signed session cookie). We do not use advertising or cross-site tracking cookies."] },
  { h: "Children", p: ["The Service is intended for businesses and is not directed to children. We do not knowingly collect personal information from children."] },
  { h: "Changes to this policy", p: ["We may update this Privacy Policy from time to time. We will revise the “last updated” date above and, for material changes, provide notice where appropriate."] },
  { h: "Contact", p: ["Questions or requests: <a href=\"mailto:support@getcoursed.com\">support@getcoursed.com</a>."] }
]);

